                add(expansion, APR.PREFAB_TYPES.Leveling, expansion)
            end
            add(expansion, APR.PREFAB_TYPES.Dungeons, "forever_dungeons")
            add(expansion, definition.prefabType, "forever_mage_aoe")
        else
            add(expansion, definition.prefabType)
